from pathlib import Path
import json,html,zipfile
P=Path(__file__).parent
names={'thread':['Pyrus Atelier','Bosc Correspondence','Espalier Folio','Russet Observatory','Nashi Reverie'],'comms':['Pyrus Pocket','Bosc Beeper','Espalier Screen','Russet Relay','Nashi Touch'],'bud':['Pyrus Pip','Bosc Button','Espalier Sprig','Russet Keepsake','Nashi Whisper']}
gifs=['https://64.media.tumblr.com/b4c09678f3c58d9c1d8cd5a678434f3b/8e9b4780f7fc5ebe-27/s250x400/f29f3f1643c8f827c4586a9776504bcb0a039ab3.gifv','https://64.media.tumblr.com/6714ee4dc78c2bff9f2abdaa6d4f0e98/8e9b4780f7fc5ebe-9b/s250x400/2a3a511ff69c46ec6428f0f1fdd13d0e73e81aaa.gifv']
css='''.pr1{--a:rgb(var(--mgrgb1,107,116,71));--b:rgb(var(--mgrgb2,151,109,94));--c:rgb(var(--mgrgb3,103,124,130));--paper:#f7f6f2;--ink:#333431;--wash:#eeede8;--grad:linear-gradient(110deg,var(--a),var(--b),var(--c));box-sizing:border-box;max-width:540px;margin:24px auto;background:var(--paper);color:var(--ink);border:1px solid var(--a);padding:30px;font:15px/1.85 Georgia,serif;position:relative;isolation:isolate;overflow-wrap:anywhere}.pr1 *{box-sizing:border-box}.pr1 a{color:var(--a)}.pr1 .pr-head{display:flex;flex-direction:column;border-bottom:1px solid var(--b);padding-bottom:20px;gap:8px}.pr1 .pr-name{font:11px/1.5 Arial,sans-serif;letter-spacing:.18em;text-transform:uppercase}.pr1 .pr-title{font:italic 38px/1.15 Georgia,serif;color:var(--b)}.pr1 .pr-media{display:flex;gap:12px;margin:24px 0}.pr1 .pr-media:empty{display:none}.pr1 .pr-media img{width:0;flex:1;min-width:0;height:150px;object-fit:cover;border:3px solid var(--paper);outline:1px solid var(--c)}.pr1 .pr-copy p{margin:0 0 18px}.pr1 :is(b,strong,u){background:var(--grad);background-clip:text;-webkit-background-clip:text;color:transparent}.pr1 :is(i,em){background:linear-gradient(110deg,var(--c),var(--b),var(--a));background-clip:text;-webkit-background-clip:text;color:transparent}.pr1 u{text-decoration-color:var(--b);text-underline-offset:4px}.pr1 .pr-foot{display:flex;align-items:center;justify-content:space-between;gap:15px;border-top:1px solid var(--c);padding-top:14px;color:var(--a);font:10px/1.6 Arial,sans-serif;letter-spacing:.16em;text-transform:uppercase}.pr1 .pr-fruit{display:block;width:35px;height:43px;background:var(--grad);border-radius:48% 48% 45% 45% / 65% 65% 35% 35%;position:relative;transform:rotate(-12deg);margin:10px}.pr1 .pr-fruit:before{content:'';position:absolute;left:17px;top:-9px;height:12px;width:3px;background:var(--b);transform:rotate(22deg)}.pr1 .pr-fruit:after{content:'';position:absolute;top:-5px;left:21px;width:16px;height:8px;background:var(--c);border-radius:100% 0}.pr1-v1{border-radius:120px 120px 8px 8px;padding-top:65px}.pr1-v1 .pr-head{text-align:center}.pr1-v1 .pr-media img{border-radius:48% 48% 42% 42% / 65% 65% 35% 35%;height:180px}.pr1-v2{border-width:1px 1px 1px 9px;box-shadow:7px 7px 0 var(--wash)}.pr1-v2 .pr-title{font-style:normal;font-size:32px}.pr1-v2 .pr-media{padding:12px;border:1px dashed var(--b);transform:rotate(-2deg)}.pr1-v3{display:grid;grid-template-columns:minmax(0,1fr) 80px;gap:20px;border-top:8px solid var(--a)}.pr1-v3 .pr-head,.pr1-v3 .pr-foot{grid-column:1/-1}.pr1-v3 .pr-media{grid-column:2;grid-row:2;margin:0;flex-direction:column}.pr1-v3 .pr-media img{width:100%;flex:none;height:110px;border-radius:50%}.pr1-v3 .pr-copy{grid-column:1;grid-row:2}.pr1-v3:has(.pr-media:empty) .pr-copy{grid-column:1/-1}.pr1-v4{border:double 5px var(--b);padding:25px}.pr1-v4 .pr-head{border-bottom:3px double var(--a)}.pr1-v4 .pr-media img{border-radius:50%;height:130px}.pr1-v4 .pr-title{letter-spacing:-.05em;font-size:44px}.pr1-v5{border-radius:8px 48px 8px 8px;border-top:14px solid var(--c)}.pr1-v5 .pr-media{gap:0}.pr1-v5 .pr-media img{height:100px;outline:0;border:0;border-bottom:5px solid var(--a)}.pr1-v5 .pr-head{border:0}.pr1-comms{max-width:350px;font:14px/1.6 Arial,sans-serif;border:5px solid var(--a);border-radius:35px;padding:24px 18px;display:flex;flex-direction:column;gap:0}.pr1-comms .pr-head{order:1}.pr1-comms .pr-title{font:22px/1.2 Georgia,serif}.pr1-comms .pr-media{order:2;justify-content:center}.pr1-comms .pr-media img{flex:none;width:65px;height:65px;border-radius:50%}.pr1-comms .pr-copy{order:3}.pr1-comms .pr-copy p{background:var(--wash);border-left:2px solid var(--b);border-radius:15px 15px 15px 3px;padding:12px;margin:0 25px 12px 0}.pr1-comms .pr-copy p:nth-child(even){margin:0 0 12px 25px;border-left:0;border-right:2px solid var(--c);border-radius:15px 15px 3px 15px}.pr1-comms .pr-foot{order:4}.pr1-comms .pr-status{order:0;font:10px/1.4 monospace;letter-spacing:.12em;color:var(--c);padding-bottom:15px}.pr1-comms.pr1-v2{border-radius:12px;border-width:12px 5px 24px;max-width:410px}.pr1-comms.pr1-v3{border-radius:6px;max-width:460px;border-top-width:28px}.pr1-comms.pr1-v4{border-radius:45px 45px 15px 15px;border-style:double;border-width:7px}.pr1-comms.pr1-v5{border-radius:25px;border-bottom-width:28px}.pr1-bud{max-width:370px;padding:22px;font-size:14px}.pr1-bud .pr-title{font-size:25px}.pr1-bud .pr-media img{height:75px}.pr1-bud.pr1-v1{padding-top:40px}.pr1-bud .pr-fruit{width:22px;height:27px}.pr1-bud .pr-copy p{margin-bottom:12px}html[color-mode="dark"] .pr1{--paper:#202321;--ink:#e5e5df;--wash:#2b302c}@media(prefers-color-scheme:dark){html:not([color-mode="light"]) .pr1{--paper:#202321;--ink:#e5e5df;--wash:#2b302c}}@media(max-width:400px){.pr1{padding:20px}.pr1-v1{padding-top:50px}.pr1 .pr-title{font-size:28px}.pr1-v3{grid-template-columns:minmax(0,1fr) 55px;gap:12px}.pr1 .pr-media img{height:110px}.pr1-comms .pr-media img{height:55px;width:55px}.pr1-bud .pr-media img{height:65px}}
'''
css += (P/'forum-fixes.css').read_text(encoding='utf-8')
(P/'pear-orchard-v1.css').write_text(css,encoding='utf-8')
(P/'pear-orchard-forum-v2.css').write_text(css,encoding='utf-8')
rows=[];cards=[];posts=[]
for kind,group in names.items():
 for n,name in enumerate(group,1):
  slug=name.lower().replace(' ','-');file=f'pear-{slug}-{kind}-{n:02}.txt'
  sample='<p>Lorem ipsum dolor sit amet, consectetur adipiscing elit. <b>Aliquam erat volutpat.</b> <i>Sed do eiusmod tempor</i> incididunt ut labore et dolore magna aliqua. <u>Ut enim ad minim veniam.</u></p>'
  if kind=='thread':sample*=3
  if kind=='comms':sample='<p>Lorem ipsum dolor sit amet.</p><p><b>Aliquam erat volutpat.</b></p><p><i>Sed do eiusmod tempor.</i> <u>Ut enim ad minim veniam.</u></p>'
  media='\n'.join(f'<img src="{g}" alt="Character GIF">' for g in gifs[:(2 if kind=='thread' and n%2 else 1)])
  code=f'[dohtml]\n<div class="pr1 pr1-{kind} pr1-v{n}">\n<div class="pr-head">\n<a class="pr-name" href="[url]">[name]</a>\n<span class="pr-title">[text]</span>\n</div>\n<div class="pr-media">\n{media}\n</div>\n<div class="pr-copy">\n{sample}\n</div>\n'+('<div class="pr-status">09:41 · Connected</div>\n' if kind=='comms' else '')+f'<div class="pr-foot"><span>{name} / '+('Delivered' if kind=='comms' else 'Pear')+'</span><span class="pr-fruit" aria-hidden="true"></span></div>\n</div>\n<link rel="stylesheet" href="https://cdn.jsdelivr.net/gh/lexdoescodingnow/templates@main/pear/pear-orchard-forum-v2.css">\n[/dohtml]'
  (P/file).write_text(code,encoding='utf-8');rows.append(dict(name=name,slug=slug,type=kind,file=file))
  example=code.replace('[name]','Haneul &amp; Taejoo').replace('[text]',name).replace('[url]','#').replace('[dohtml]','').replace('[/dohtml]','')
  cards.append(f'<section><h2>{name} · {kind}</h2><div class="preview">{example}</div><button onclick="copy(this)">Copy template</button><button onclick="update(this)">Update preview</button><textarea aria-label="{name} editable posting code">{html.escape(code)}</textarea></section>')
  posts.append(f'[size=4][b]{len(rows):02} · {name}[/b][/size]\n\n{code}\n\n[code]\n{code}\n[/code]')
(P/'designs.json').write_text(json.dumps(rows,indent=2))
page='''<!doctype html><html lang="en" color-mode="light"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pear · Haneul & Taejoo</title><style>body{margin:0;background:#e7e7e1;color:#30352f;font:15px/1.6 system-ui;--mgrgb1:105,120,65;--mgrgb2:151,97,110;--mgrgb3:65,126,132}main{max-width:900px;margin:auto;padding:24px}h1{font:70px Georgia}section{margin:45px 0;padding:20px;border:1px solid #999}textarea{width:100%;height:230px;box-sizing:border-box;margin-top:15px}button{padding:10px;margin:5px}html[color-mode=dark] body{background:#151916;color:#ddd;--mgrgb1:183,200,138;--mgrgb2:219,159,173;--mgrgb3:133,201,204}</style><link rel="stylesheet" href="pear-orchard-forum-v2.css"><main><h1>Pear</h1><p>Haneul & Taejoo · fifteen orchard studies</p><button onclick="document.documentElement.setAttribute('color-mode',document.documentElement.getAttribute('color-mode')==='light'?'dark':'light')">Light / dark</button>'''+''.join(cards)+'''</main><script>function update(b){let s=b.closest('section'),v=s.querySelector('textarea').value.replace(/\[\/?dohtml\]/gi,'').replace(/\[(\/)?(b|i|u)\]/gi,'<$1$2>');s.querySelector('.preview').innerHTML=v;s.querySelector('textarea').value='[dohtml]'+v+'[/dohtml]'}async function copy(b){let t=b.closest('section').querySelector('textarea');try{await navigator.clipboard.writeText(t.value);b.textContent='Copied'}catch(e){t.focus();t.select();b.textContent='Selected — Ctrl+C'}}</script></html>'''
(P/'pear-collection-preview.html').write_text(page,encoding='utf-8')
(P/'pear-forum-masterpost.txt').write_text('[align=center][H1]PEAR[/H1][/align]\n\n'+'\n\n'.join(posts),encoding='utf-8')
(P/'README.md').write_text('# Pear · Haneul & Taejoo\n\n[Preview and editable code](pear-collection-preview.html) · [Forum masterpost](pear-forum-masterpost.txt) · [Download collection](pear-collection.zip)\n\n'+ '\n'.join(f'- {r["type"].title()}: [{r["name"]}]({r["file"]})' for r in rows)+'\n\nNames, links, titles, GIFs and writing appear before decoration. Keep the complete dohtml block. Edit ordinary HTML paragraphs; the browser preview’s Update preview button also converts [b], [i] and [u] into supported HTML. Direct forum snippets use HTML emphasis. Member RGB variables colour frames, headers and emphasis. Explicit Blue Hour light/dark mode takes precedence over system mode. Device status is decorative. Remove images to omit portraits. Bud samples are below 100 words. No JavaScript is needed in forum posts.\n',encoding='utf-8')
with zipfile.ZipFile(P/'pear-collection.zip','w',zipfile.ZIP_DEFLATED) as z:
 for f in P.iterdir():
  if f.suffix in ('.txt','.css','.html','.md','.json'):z.write(f,f.name)
print('Built 15 Pear designs, preview, forum masterpost and ZIP.')

